"""Random diagnostic codes: some drawn from the documented table, some
deliberately not, so that "which codes are real" cannot be guessed from
the generator alone."""

DOCUMENTED = (0, 101, 102, 103, 201, 202, 301)


def generate(rng, count):
    builders = (_documented, _undocumented, _near_a_real_code, _extreme)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, codes, description=""):
    lines = [str(c) for c in codes]
    return {
        "name": name,
        "stdin": "\n".join(lines) + "\n",
        "description": description,
    }


def _documented(rng, index):
    codes = [rng.choice(DOCUMENTED) for _ in range(5)]
    return _case("a run of documented codes #%d" % index, codes)


def _undocumented(rng, index):
    codes = []
    while len(codes) < 5:
        c = rng.randint(-500, 999)
        if c not in DOCUMENTED:
            codes.append(c)
    return _case("a run of codes not in the table #%d" % index, codes,
                 "None of these are documented -- every one should come "
                 "back -1.")


def _near_a_real_code(rng, index):
    base = rng.choice(DOCUMENTED)
    candidates = [base + o for o in (-3, -2, -1, 1, 2, 3)
                  if (base + o) not in DOCUMENTED]
    codes = [base] + rng.sample(candidates, min(3, len(candidates)))
    return _case("codes clustered around a real one #%d" % index, codes,
                 "Only the exact documented code should classify -- its "
                 "neighbours are unknown.")


def _extreme(rng, index):
    codes = [rng.choice((-2147483648, 2147483647, 0, 301))]
    codes.extend(rng.randint(-1000, 1000) for _ in range(3))
    return _case("extreme int32 values mixed in #%d" % index, codes)
